CREATE TABLE "albums" ("spotify_id" TEXT NOT NULL, "name" TEXT NOT NULL, "artist_id" TEXT NOT NULL, "artist_name" TEXT NOT NULL, "image_url" TEXT NULL, "release_date" TEXT NULL, "total_tracks" INTEGER NULL, "is_liked" INTEGER NOT NULL DEFAULT 0 CHECK ("is_liked" IN (0, 1)), "updated_at" INTEGER NULL, PRIMARY KEY ("spotify_id"));
CREATE TABLE "artists" ("spotify_id" TEXT NOT NULL, "name" TEXT NOT NULL, "image_url" TEXT NULL, "image_small" TEXT NULL, "followers" INTEGER NULL, "is_followed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_followed" IN (0, 1)), "updated_at" INTEGER NULL, PRIMARY KEY ("spotify_id"));
CREATE TABLE "catalog_cache_entries" ("key" TEXT NOT NULL, "payload" TEXT NOT NULL, "fetched_at" INTEGER NOT NULL, "last_accessed_at" INTEGER NOT NULL, "payload_version" INTEGER NOT NULL, "resource_type" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "import_roots" ("id" TEXT NOT NULL, "mechanism" TEXT NOT NULL, "root_locator" TEXT NOT NULL, "display_path" TEXT NOT NULL, "added_at" INTEGER NOT NULL, "media_scope" TEXT NOT NULL DEFAULT 'audio', PRIMARY KEY ("id"));
CREATE TABLE "local_files" ("library_id" TEXT NOT NULL, "mechanism" TEXT NOT NULL, "locator" TEXT NOT NULL, "display_path" TEXT NOT NULL, "deduplication_key" TEXT NOT NULL, "availability_status" TEXT NOT NULL DEFAULT 'available', "last_scanned_at" INTEGER NOT NULL, "import_root_locator" TEXT NULL, "album_artist" TEXT NULL, "album_group_key" TEXT NULL, "track_number" INTEGER NULL, "track_total" INTEGER NULL, "disc_number" INTEGER NULL, "disc_total" INTEGER NULL, "genre" TEXT NULL, "release_year" INTEGER NULL, "artwork_path" TEXT NULL, "artwork_mime_type" TEXT NULL, "added_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "is_video" INTEGER NOT NULL DEFAULT 0 CHECK ("is_video" IN (0, 1)), PRIMARY KEY ("library_id"));
CREATE TABLE "playlist_tracks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "playlist_id" INTEGER NOT NULL, "track_spotify_id" TEXT NOT NULL, "position" INTEGER NOT NULL);
CREATE TABLE "playlists" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "spotify_id" TEXT NULL, "image_url" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "radios" ("seed_id" TEXT NOT NULL, "seed_type" TEXT NOT NULL, "title" TEXT NOT NULL, "image_url" TEXT NULL, "is_followed" INTEGER NOT NULL DEFAULT 1 CHECK ("is_followed" IN (0, 1)), "updated_at" INTEGER NULL, PRIMARY KEY ("seed_id", "seed_type"));
CREATE TABLE "stream_channels" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "playlist_id" INTEGER NOT NULL, "tvg_id" TEXT NULL, "title" TEXT NOT NULL, "logo" TEXT NULL, "group_title" TEXT NULL, "stream_url" TEXT NOT NULL, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "position" INTEGER NOT NULL, "live_status" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "stream_playlists" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "title" TEXT NOT NULL, "source_kind" TEXT NOT NULL, "source_uri" TEXT NOT NULL, "image_url" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "last_refreshed" INTEGER NULL);
CREATE TABLE "tracks" ("spotify_id" TEXT NOT NULL, "name" TEXT NOT NULL, "artist_id" TEXT NOT NULL, "artist_name" TEXT NOT NULL, "album_id" TEXT NULL, "album_name" TEXT NULL, "album_image" TEXT NULL, "duration_ms" INTEGER NULL, "youtube_video_id" TEXT NULL, "youtube_resolved_at" INTEGER NULL, "play_count" INTEGER NOT NULL DEFAULT 0, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "last_played_at" INTEGER NULL, PRIMARY KEY ("spotify_id"));
